<?php
namespace App\Services;
use App\Enums\BookingStatus;use App\Enums\VehicleStatus;use App\Models\Booking;use Illuminate\Support\Facades\DB;use Illuminate\Validation\ValidationException;
class VehicleCheckoutService{public function checkout(Booking $booking,array $data,int $userId){return DB::transaction(function()use($booking,$data,$userId){$booking=Booking::query()->lockForUpdate()->with('vehicle')->findOrFail($booking->id);if(!in_array($booking->status,[BookingStatus::CONFIRMED,BookingStatus::READY_FOR_PICKUP],true))throw ValidationException::withMessages(['booking'=>'Booking belum eligible untuk checkout.']);if($data['odometer']<$booking->vehicle->current_odometer)throw ValidationException::withMessages(['odometer'=>'Odometer tidak boleh lebih rendah dari kendaraan.']);$checkout=\App\Models\VehicleCheckout::create(['booking_id'=>$booking->id,'vehicle_id'=>$booking->vehicle_id,'checked_by'=>$userId,'checkout_datetime'=>now(),'odometer'=>$data['odometer'],'fuel_level'=>$data['fuel_level'],'notes'=>$data['notes']??null]);foreach($data['items'] as $item)$checkout->items()->create($item);$booking->update(['status'=>BookingStatus::IN_USE]);$booking->vehicle->update(['status'=>VehicleStatus::IN_USE,'current_odometer'=>$data['odometer']]);return $checkout;});}}
